config:
events {}

http {

    include /etc/nginx/mime.types;

    default_type application/octet-stream;

    sendfile on;

    map $http_upgrade $connection_upgrade {

        default upgrade;

        "" close;

    }

    server {
        listen 80 default_server;
        listen [::]:80 default_server;
        server_name _;
        location ^~ /.well-known/acme-challenge/ {
            proxy_pass https://acme.internal:8443/api/acme-challenge/;
            proxy_set_header Host $host;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Real-IP $remote_addr;
        }
        location ^~ / {
            return 404;
        }
    }

    server {
        listen 443 ssl;
        listen [::]:443 ssl;
        listen 443 quic reuseport;
        listen [::]:443 quic reuseport;
        add_header Alt-Svc 'h3=":443"; ma=86400' always;
        server_name alpha.home.arpa;
        location ^~ /.well-known/acme-challenge/ {
            proxy_pass https://acme.internal:8443/api/acme-challenge/;
            proxy_set_header Host $host;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Real-IP $remote_addr;
        }
        ssl_certificate /var/lib/proxycore/candidates/rev-3/nginx/certs/cert-alpha.crt;
        ssl_certificate_key /var/lib/proxycore/candidates/rev-3/nginx/certs/cert-alpha.key;
        ssl_protocols TLSv1.2 TLSv1.3;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_http_version 1.1;
        proxy_connect_timeout 5s;
        proxy_send_timeout 60s;
        proxy_read_timeout 60s;
        client_header_timeout 15s;
        client_max_body_size 10m;
        proxy_ssl_verify on;
        proxy_cache proxycore_cache;
        location = /bare {
            return 302 /;
        }
        location = /old {
            return 301 "https://example.com/new path";
        }
        location /api/v1 {
            proxy_pass https://10.0.0.50:8443/v1/;
        }
        location /api {
            proxy_pass https://10.0.0.50:8443;
        }
        location / {
            proxy_pass https://10.0.0.50:8443;
        }
    }

    server {
        listen 80;
        listen [::]:80;
        server_name zeta.home.arpa;
        location ^~ /.well-known/acme-challenge/ {
            proxy_pass https://acme.internal:8443/api/acme-challenge/;
            proxy_set_header Host $host;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Real-IP $remote_addr;
        }
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_http_version 1.1;
        proxy_send_timeout 120s;
        proxy_read_timeout 120s;
        client_header_timeout 20s;
        client_max_body_size 50m;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $connection_upgrade;
        proxy_buffering off;
        proxy_set_header x-greeting "hello world";
        proxy_set_header x-quote "say \"hi\" \\ bye";
        proxy_set_header x-empty "";
        # comment
        proxy_connect_timeout 3s; # trailing
        add_header X-A b;
        location / {
            proxy_pass http://[fd00::20]:9000;
            proxy_buffering off;
        }
    }

}

stream {
    server {
        listen [::]:5353 udp;
        proxy_pass [fd00::53]:53;
        proxy_timeout 60s;
    }
}

